content:
（Type Gymnastics）指的是利用 TypeScript 类型系统的各种特性，编写复杂而精确的类型定义。本文将系统性地介绍 TypeScript 高级类型技巧，帮助读者掌握条件类型、映射类型、模板字面量类型等核心概念，以及如何将这些技术应用于实际项目中。</p><h2 id="typescript-basics">TypeScript 类型系统基础</h2><p>在深入高级类型之前，我们需要确保对 TypeScript 类型系统的基础有扎实的理解。TypeScript 的类型系统是渐进式的，允许从宽松的类型注解逐步过渡到严格的类型检查。</p><h3>基本类型与类型推断</h3><p>TypeScript 能够根据变量的初始化值自动推断其类型。这种类型推断能力是 TypeScript 智能化设计的核心。</p><pre><code>// 基本类型推断
const name = '张三'  // string
const age = 25       // number
const isActive = true  // boolean

// 字面量类型推断
const status = 'pending'  // 'pending' (字面量类型)

// 对象类型推断
const user = {
  name: '李四',
  age: 30
}
// 推断类型: { name: string; age: number }

// 数组类型推断
const numbers = [1, 2, 3]  // number[]
const mixed = [1, 'a', true]  // (string | number | boolean)[]

// 函数返回类型推断
const add = (a: number, b: number) => a + b
// 推断返回类型: number
</code></pre><h3>类型收窄与守卫</h3><p>类型收窄（Narrowing）是 TypeScript 在控制流分析中自动缩小类型范围的过程。类型守卫（Type Guards）帮助我们在条件分支中获得更精确的类型信息。</p><pre><code>// typeof 类型守卫
function processValue(value: string | number) {
  if (typeof value === 'string') {
    return value.toUpperCase()  // value 在这里是 string
  }
  return value.toFixed(2)  // value 在这里是 number
}

// instanceof 类型守卫
class Dog {
  bark() { console.log('汪汪') }
}

class Cat {
  meow() { console.log('喵喵') }
}

function makeSound(animal: Dog | Cat) {
  if (animal instanceof Dog) {
    animal.bark()
  } else {
    animal.meow()
  }
}

// 自定义类型守卫
interface Fish {
  swim(): void
}

interface Bird {
  fly(): void
}

function isFish(pet: Fish | Bird): pet is Fish {
  return (pet as Fish).swim !== undefined
}

function move(pet: Fish | Bird) {
  if (isFish(pet)) {
    pet.swim()
  } else {
    pet.fly()
  }
}
</code></pre><h2 id="conditional-types">条件类型详解</h2><p>条件类型（Conditional Types）是 TypeScript 2.8 引入的强大特性，它允许我们根据类型之间的关系来派生出新的类型。</p><h3>条件类型基础</h3><p>条件类型的基本语法是 T extends U ? X : Y，意思是如果类型 T 可以赋值给类型 U，则条件成立，结果为类型 X，否则结果为类型 Y。</p><pre><code>// 基础条件类型
type IsString&lt;T&gt; = T extends string ? true : false

type A = IsString&lt;string&gt;  // true
type B = IsString&lt;number&gt;  // false
type C = IsString&lt;'hello'&gt;  // true (字面量类型 extends string)

// 条件类型与泛型
type ArrayElement&lt;T&gt; = T extends (infer U)[] ? U : never

type D = ArrayElement&lt;string[]&gt;  // string
type E = ArrayElement&lt;number[]&gt;  // number
type F = ArrayElement&lt;string | number&gt;  // never

// 从函数提取返回类型
type ReturnType&lt;T&gt; = T extends (...args: any[]) =&gt; infer R ? R : never

function getUser() {
  return { id: 1, name: '张三' }
}

type User = ReturnType&lt;typeof getUser&gt;
// { id: number; name: string }

// 从构造函数提取实例类型
type InstanceType&lt;T&gt; = T extends new (...args: any[]) =&gt; infer R ? R : never

class UserClass {
  constructor(public name: string) {}
}

type UserInstance = InstanceType&lt;typeof UserClass&gt;
// UserClass
</code></pre><h3>分布式条件类型</h3><p>当条件类型的类型参数是联合类型时，TypeScript 会自动

条件类型到联合类型的每个成员。</p><pre><code>// 分布式条件类型
type ToArray&lt;T&gt; = T extends any ? T[] : never

type G = ToArray&lt;string | number&gt;
// 等价于: ToArray&lt;string&gt; | ToArray&lt;number&gt;
// 结果: string[] | number[]

// 禁止分布式（将类型参数包装在元组中）
type ToArrayNonDist&lt;T&gt; = [T] extends [any] ? T[] : never

type H = ToArrayNonDist&lt;string | number&gt;
// 结果: (string | number)[]

// 实际应用：过滤联合类型
type Exclude&lt;T, U&gt; = T extends U ? never : T

type I = Exclude&lt;'a' | 'b' | 'c', 'a' | 'b'&gt;
// 结果: 'c'

type J = Extract&lt;string | number | boolean, string&gt;
// 结果: string

// NonNullable 实现
type NonNullable&lt;T&gt; = T extends null | undefined ? never : T

type K = NonNullable&lt;string | null | undefined&gt;
// 结果: string
</code></pre><h3>递归条件类型</h3><p>TypeScript 支持递归条件类型，可以用于处理深度嵌套的数据结构，但需要注意避免无限递归。</p><pre><code>// 深度只读类型
type DeepReadonly&lt;T&gt; = T extends (infer U)[]
  ? ReadonlyArray&lt;DeepReadonly&lt;U&gt;&gt;
  : T extends object
  ? { readonly [K in keyof T]: DeepReadonly&lt;T[K]&gt; }
  : T

interface Config {
  database: {
    host: string
    port: number
    users: { name: string; password: string }[]
  }
}

type ReadonlyConfig = DeepReadonly&lt;Config&gt;
// 所有嵌套属性都变为只读

// 深度可选类型
type DeepPartial&lt;T&gt; = T extends (infer U)[]
  ? DeepPartial&lt;U&gt;[]
  : T extends object
  ? { [K in keyof T]?: DeepPartial&lt;T[K]&gt; }
  : T

// 平铺嵌套数组
type Flatten&lt;T&gt; = T extends (infer U)[]
  ? U extends (infer V)[]
    ? Flatten&lt;V&gt;
    : U
  : T

type L = Flatten&lt;number[][]&gt;  // number
type M = Flatten&lt;string[][][]&gt;  // string
</code></pre><h2 id="mapped-types">映射类型</h2><p>映射类型（Mapped Types）允许我们通过遍历现有类型的键来创建新类型。这是 TypeScript 实现类型转换的强大工具。</p><h3>基础映射类型</h3><pre><code>// 将所有属性转换为可选
type Optional&lt;T&gt; = { [K in keyof T]?: T[K] }

// 将所有属性转换为只读
type Readonly&lt;T&gt; = { readonly [K in keyof T]: T[K] }

// 将所有属性转换为必需
type Required&lt;T&gt; = { [K in keyof T]-?: T[K] }

// 映射类型与 keyof
type KeysOfType&lt;T, U&gt; = { [K in keyof T]: T[K] extends U ? K : never }[keyof T]

interface User {
  id: number
  name: string
  age: number
  email: string
  createdAt: Date
}

type StringKeys = KeysOfType&lt;User, string&gt;
// 'name' | 'email'

// 同态与非同态映射类型
// 同态：preserve 原始类型的修饰符（readonly、?）
type MyReadonly&lt;T&gt; = { readonly [K in keyof T]: T[K] }
// 保持原有的可选/必选修饰符
type MyOptional&lt;T&gt; = { [K in keyof T]?: T[K] }

// 非同态：会清除修饰符
type Stringify&lt;T&gt; = { [K in keyof T]: string }
</code></pre><h3>映射类型修饰符</h3><p>映射类型语法支持 + 和 - 前缀来添加或移除 readonly 和可选修饰符。</p><pre><code>// 添加可选修饰符
type AddOptional&lt;T, K extends keyof T&gt; = {
  [P in keyof T]: P extends K ? T[P] | undefined : T[P]
}

// 移除可选修饰符
type RemoveOptional&lt;T, K extends keyof T&gt; = {
  [P in keyof T]: P extends K ? T[P] : T[P]
} &amp; {
  [P in K]-?: T[P]
}

// 添加 readonly 修饰符
type AddReadonly&lt;T, K extends keyof T&gt; = {
  readonly [P in K]: T[P]
} &amp; {
  [P in keyof T as P extends K ? never : P]: T[P]
}

// 条件映射类型
type MappedWithCondition&lt;T, K extends keyof T, U&gt; = {
  [P in K]: T[P] extends U ? T[P] : never
}

// 实际应用：类型键重映射
type Getters&lt;T&gt; = {
  [K in keyof T as `get${Capitalize&lt;string &amp; K&gt;}`]: () =&gt; T[K]
}

interface User {
  name: string
  age: number
}

type UserGetters = Getters&lt;User&gt;
// { getName: () =&gt; string; getAge: () =&gt; number }
</code></pre><h3>模板字面量与映射类型结合</h3><pre><code>// 创建 getter 和 setter
type GettersSetters&lt;T&gt; = {
  [K in keyof T as `get${Capitalize&lt;string &amp; K&gt;}`]: () =&gt; T[K]
} &amp; {
  [K in keyof T as `set${Capitalize&lt;string &amp; K&gt;}`]: (value: T[K]) =&gt; void
}

// 创建事件映射
type EventMap&lt;T&gt; = {
  [K in keyof T as `${string &amp; K}Changed`]: CustomEvent&lt;T[K]&gt;
}

// 创建路由参数类型
type ExtractRouteParams&lt;T extends string&gt; =
  T extends `${infer _Start}:${infer Param}/${infer Rest}`
    ? Param | ExtractRouteParams&lt;Rest&gt;
    : T extends `${infer _Start}:${infer Param}`
    ? Param
    : never

type Params = ExtractRouteParams&lt;'/users/:userId/posts/:postId'&gt;
// 'userId' | 'postId'
</code></pre><h2 id="template-literals">模板字面量类型</h2><p>TypeScript 4.1 引入了模板字面量类型（Template Literal Types），允许我们使用 JavaScript 的模板字符串语法来构造新的类型。</p><h3>基础模板字面量类型</h3><pre><code>// 基础模板字面量
type World = 'World'
type Greeting = `Hello, ${World}!`  // 'Hello, World!'

// 连接字符串类型
type EmailLocaleIDs = 'welcome-email' | 'email-heading'
type FooterLocaleIDs = 'footer-title' | 'footer-slogan'

type AllLocaleIDs = `${EmailLocaleIDs}_id` | `${FooterLocaleIDs}_id`
// 'welcome-email_id' | 'email-heading_id' | 'footer-title_id' | 'footer-slogan_id'

// 使用通用约束
type PropEventSource&lt;T&gt; = {
  on&lt;K extends string &amp; keyof T&gt;(
    eventName: `${K}Changed`,
    callback: (newValue: T[K]) =&gt; void
  ): void
}

declare function makeWatchedObject&lt;T&gt;(obj: T): T &amp; PropEventSource&lt;T&gt;

const person = makeWatchedObject({
  firstName: '张三',
  lastName: '李四',
  age: 26
})

person.on('firstNameChanged', (newName) =&gt; {
  console.log(`名字改为: ${newName}`)
})
</code></pre><h3>内置字符串操作类型</h3><p>TypeScript 提供了一些内置的字符串操作类型，帮助我们处理和转换字符串类型。</p><pre><code>// Uppercase、Lowercase、Capitalize、Uncapitalize
type Greet = 'hello, world'
type Shout = Uppercase&lt;Greet&gt;  // 'HELLO, WORLD'
type Whisper = Lowercase&lt;Shout&gt;  // 'hello, world'
type Proper = Capitalize&lt;'hello'&gt;  // 'Hello'
type Unproper = Uncapitalize&lt;'Hello'&gt;  // 'hello'

// 实际应用：自动生成类型安全的 SQL
type TableName&lt;T extends string&gt; = {
  table: T
}

type Column&lt;T, C extends string&gt; = {
  select: () =&gt; C
  where: (value: T) =&gt; { table: string; column: C; value: T }
}

type QueryBuilder&lt;T, K extends string&gt; = {
  [C in K]: Column&lt;T, C&gt;
}

// 路由类型系统
type Route&lt;Path extends string&gt; = {
  path: Path
  params: ExtractRouteParams&lt;Path&gt;
  query: Record&lt;string, string | number&gt;
}

function createRoute&lt;Path extends string&gt;(
  route: Route&lt;Path&gt;
): Route&lt;Path&gt; {
  return route
}

const r = createRoute({
  path: '/users/:userId/posts/:postId',
  params: ['userId', 'postId'],
  query: {}
})
</code></pre><h2 id="utility-types">内置工具类型实现</h2><p>TypeScript 提供了一系列内置的工具类型。理解它们的实现原理有助于我们创建自定义的工具类型。</p><h3>常用工具类型实现</h3><pre><code>// Partial&lt;T&gt; - 将所有属性变为可选
type MyPartial&lt;T&gt; = {
  [P in keyof T]?: T[P]
}

// Required&lt;T&gt; - 移除所有可选修饰符
type MyRequired&lt;T&gt; = {
  [P in keyof T]-?: T[P]
}

// Readonly&lt;T&gt; - 将所有属性变为只读
type MyReadonly&lt;T&gt; = {
  readonly [P in keyof T]: T[P]
}

// Pick&lt;T, K&gt; - 从 T 中选取一组属性 K
type MyPick&lt;T, K extends keyof T&gt; = {
  [P in K]: T[P]
}

// Omit&lt;T, K&gt; - 从 T 中移除一组属性 K
type MyOmit&lt;T, K extends keyof T&gt; = {
  [P in Exclude&lt;keyof T, K&gt;]: T[P]
}

// Record&lt;K, V&gt; - 创建键类型为 K、值类型为 V 的对象类型
type MyRecord&lt;K extends keyof any, V&gt; = {
  [P in K]: V
}

// Extract&lt;T, U&gt; - 从 T 中提取可赋值给 U 的类型
type MyExtract&lt;T, U&gt; = T extends U ? T : never

// Exclude&lt;T, U&gt; - 从 T 中排除可赋值给 U 的类型
type MyExclude&lt;T, U&gt; = T extends U ? never : T

// ReturnType&lt;T&gt; - 获取函数返回类型
type MyReturnType&lt;T extends (...args: any) =&gt; any&gt; =
  T extends (...args: any) =&gt; infer R ? R : never

// Parameters&lt;T&gt; - 获取函数参数类型为元组
type MyParameters&lt;T extends (...args: any) =&gt; any&gt; =
  T extends (...args: infer P) =&gt; any ? P : never
</code></pre><h3>高级工具类型</h3><pre><code>// Awaited&lt;T&gt; - 获取 Promise 的解析类型
type MyAwaited&lt;T&gt; = T extends null | undefined
  ? T
  : T extends object &amp; { then(onfulfilled: infer F): any }
  ? F extends (value: infer V, ...args: any) =&gt; any
    ? MyAwaited&lt;V&gt;
    : never
  : T

// NonNullable&lt;T&gt; - 排除 null 和 undefined
type MyNonNullable&lt;T&gt; = T extends null | undefined ? never : T

// ConstructorParameters&lt;T&gt; - 获取构造函数参数类型
type MyConstructorParameters&lt;
  T extends new (...args: any) =&gt; any
&gt; = T extends new (...args: infer P) =&gt; any ? P : never

// InstanceType&lt;T&gt; - 获取实例类型
type MyInstanceType&lt;T extends new (...args: any) =&gt; any&gt; =
  T extends new (...args: any) =&gt; infer R ? R : never

// ThisParameterType&lt;T&gt; - 获取函数 this 参数类型
type MyThisParameterType&lt;T&gt; = T extends (this: infer This, ...args: any) =&gt; any
  ? This
  : unknown

// OmitThisParameter&lt;T&gt; - 移除函数 this 参数
type MyOmitThisParameter&lt;T&gt; = T extends (...args: infer P) =&gt; infer R
  ? (...args: P) =&gt; R
  : T
</code></pre><h2 id="recursion">递归类型与高级模式</h2><p>递归类型允许我们处理无限嵌套的数据结构，这在处理 JSON、树形结构等场景中非常有用。</p><h3>JSON 类型</h3><pre><code>// 递归定义 JSON 类型
type JSONValue =
  | string
  | number
  | boolean
  | null
  | JSONValue[]
  | { [key: string]: JSONValue }

// 更严格的 JSON schema
type JSONSchema = {
  type: 'object'
  properties: { [key: string]: JSONSchema }
  required?: string[]
} | {
  type: 'array'
  items: JSONSchema
} | {
  type: 'string'
  minLength?: number
  maxLength?: number
  pattern?: string
} | {
  type: 'number'
  minimum?: number
  maximum?: number
}

// 深度属性访问类型
type DeepGet&lt;T, K extends string&gt; =
  K extends `${infer P}.${infer R}`
    ? P extends keyof T
      ? DeepGet&lt;T[P], R&gt;
      : never
    : K extends keyof T
    ? T[K]
    : never

interface Company {
  name: string
  address: {
    city: string
    zip: string
  }
  employees: {
    name: string
    salary: number
  }[]
}

type City = DeepGet&lt;Company, 'address.city'&gt;  // string
type FirstEmployeeName = DeepGet&lt;Company, 'employees.0.name'&gt;  // string
</code></pre><h3>斐波那契数列类型</h3><pre><code>// 编译时斐波那契数列
type Fibonacci&lt;N extends number, 
               Curr extends number = 0, 
               Next extends number = 1,
               Count extends any[] = []&gt; =
  Count['length'] extends N
    ? Curr
    : Fibonacci&lt;N, Next, Add&lt;Curr, Next&gt;, [...Count, 0]&gt;

// 编译时加法
type Add&lt;A extends number, B extends number&gt; =
  [...{length: A}, ...{length: B}]['length']

type Fib5 = Fibonacci&lt;5&gt;  // 5
type Fib10 = Fibonacci&lt;10&gt;  // 55

// 更高效的斐波那契（使用元组索引）
type BuildTuple&lt;N extends number, T extends any[] = []&gt; =
  T['length'] extends N ? T : BuildTuple&lt;N, [...T, any]&gt;

type AddNumbers&lt;A extends number, B extends number&gt; =
  [...BuildTuple&lt;A&gt;, ...BuildTuple&lt;B&gt;]['length']

// 比较数字大小
type LessThan&lt;A extends number, B extends number&gt; =
  BuildTuple&lt;A&gt; extends [...BuildTuple&lt;B&gt;, ...any]
    ? true
    : false
</code></pre><h2 id="practical-patterns">实战技巧与最佳实践</h2><p>在实际项目中，灵活运用高级类型技巧可以使代码更加类型安全、易于维护。</p><h3>类型安全的 EventEmitter</h3><pre><code>type EventMap = {
  userLogin: { userId: string; timestamp: Date }
  userLogout: { userId: string }
  orderCreated: { orderId: string; total: number }
  error: { code: number; message: string }
}

class TypedEventEmitter&lt;T extends Record&lt;string, any&gt;&gt; {
  private handlers = new Map&lt;keyof T, Set&lt;Function&gt;&gt;()

  on&lt;K extends keyof T&gt;(event: K, handler: (data: T[K]) =&gt; void): this {
    if (!this.handlers.has(event)) {
      this.handlers.set(event, new Set())
    }
    this.handlers.get(event)!.add(handler)
    return this
  }

  off&lt;K extends keyof T&gt;(event: K, handler: (data: T[K]) =&gt; void): this {
    this.handlers.get(event)?.delete(handler)
    return this
  }

  emit&lt;K extends keyof T&gt;(event: K, data: T[K]): void {
    this.handlers.get(event)?.forEach(handler =&gt; handler(data))
  }
}

const emitter = new TypedEventEmitter&lt;EventMap&gt;()

emitter.on('userLogin', ({ userId, timestamp }) =&gt; {
  console.log(`用户 ${userId} 于 ${timestamp} 登录`)
})

// 错误：类型不匹配
// emitter.emit('userLogin', { userId: '123' })  // Error: 缺少 timestamp
</code></pre><h3>类型安全的 API 客户端</h3><pre><code>// 定义 API schema
type APIRoutes = {
  'GET /users': {
    response: { users: User[] }
    query: { page?: number; limit?: number }
  }
  'GET /users/:id': {
    response: { user: User }
    params: { id: string }
  }
  'POST /users': {
    body: CreateUserInput
    response: { user: User }
  }
  'DELETE /users/:id': {
    params: { id: string }
    response: { success: boolean }
  }
}

type APIResponse&lt;Route extends keyof APIRoutes&gt; = APIRoutes[Route]['response']
type APIParams&lt;Route extends keyof APIRoutes&gt; = APIRoutes[Route] extends { params: infer P } ? P : {}
type APIQuery&lt;Route extends keyof APIRoutes&gt; = APIRoutes[Route] extends { query: infer Q } ? Q : {}
type APIBody&lt;Route extends keyof APIRoutes&gt; = APIRoutes[Route] extends { body: infer B } ? B : never

// 简化版实现
type RequestMethod = 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH'
type RequestPath = Extract&lt;keyof APIRoutes, `${RequestMethod} ${string}`&gt;

interface RequestConfig&lt;Route extends RequestPath&gt; {
  method: Route extends `${infer M} ${string}` ? M : never
  path: Route extends `${string} ${infer P}` ? P : never
}

// 使用示例
async function api&lt;Route extends RequestPath&gt;(
  config: RequestConfig&lt;Route&gt;
): Promise&lt;APIResponse&lt;Route&gt;&gt; {
  // 实现请求逻辑
  return {} as APIResponse&lt;Route&gt;
}

const users = await api&lt;'GET /users'&gt;({
  method: 'GET',
  path: '/users'
})
</code></pre><h3>类型守卫与验证</h3><pre><code>// 运行时类型验证
type ValidationRule&lt;T&gt; = (value: unknown) =&gt; value is T

function isString(value: unknown): value is string {
  return typeof value === 'string'
}

function isNumber(value: unknown): value is number {
  return typeof value === 'number' &amp;&amp; !Number.isNaN(value)
}

function isObject(value: unknown): value is Record&lt;string, unknown&gt; {
  return typeof value === 'object' &amp;&amp; value !== null &amp;&amp; !Array.isArray(value)
}

function hasProperty&lt;Obj, Key extends string&gt;(
  obj: Obj,
  key: Key
): obj is Obj &amp; Record&lt;Key, unknown&gt; {
  return key in (obj as object)
}

// 类型守卫工厂
function isOfType&lt;T&gt;(
  typeGuard: (value: unknown) =&gt; value is T
): (value: unknown) =&gt; value is T {
  return typeGuard
}

const isStringArray = (value: unknown): value is string[] =&gt;
  Array.isArray(value) &amp;&amp; value.every(isString)

// 联合类型守卫
function isOneOf&lt;T&gt;(value: T, candidates: readonly T[]): value is T {
  return candidates.includes(value)
}

const Direction = ['up', 'down', 'left', 'right'] as const
type Direction = typeof Direction[number]

function isDirection(value: unknown): value is Direction {
  return isOneOf(value, Direction)
}
